-- Dumping data for `nora_knowledge`
INSERT INTO `nora_knowledge` (`id`, `intent`, `keywords`, `answer_text`, `action_link`, `created_at`, `updated_at`) VALUES
('1', 'แนะนำสถานที่ท่องเที่ยวให้หน่อย', 'แหล่งท่องเที่ยว,สถานที่ท่องเที่ยว,แนะนำแหล่งท่องเที่ยว,มาเมืองลุง,ข้อมูลด้านการท่องเที่ยว', 'ถ้าเกี่ยวกับการท่องเที่ยว น้องแนะนำให้ไปที่เว็บไซต์  \"มาเมืองลุง\" นะคะ', 'http://www.ma-muanglung.com', '2026-08-26 06:29:22', '2026-08-26 06:29:22'),
('2', 'คำขวัญประจำจังหวัดพัทลุงและมรดกทางวัฒนธรรมคืออะไร?', 'คำขวัญ, คำขวัญจังหวัด, พัทลุงคืออะไร, สวนขวัญเมือง, มรดก, โนรา, มโนราห์', '✨ **คำขวัญจังหวัดพัทลุง**: \"เมืองหนังโนรา อู่นาข้าว พราวน้ำตก แหล่งนกน้ำ ถ้ำเย็นตา ภูเขาอกทะลุ น้ำพุร้อน\"\n\nศิลปะการแสดง **\"โนรา\" (Nora)** ได้รับการขึ้นทะเบียนจาก UNESCO ให้เป็นมรดกทางวัฒนธรรมที่จับต้องไม่ได้ของมนุษยชาติ ซึ่งพัทลุงเป็นแผ่นดินต้นกำเนิดแห่งมนต์ขลังนี้ค่ะ ', 'http://www.ma-muanglung.go.th', '2026-08-26 06:29:22', '2026-08-26 06:29:22'),
('3', 'ติดต่อศาลากลางและหน่วยงานภายในจังหวัดได้อย่างไร?', 'เบอร์โทร, เบอร์ติดต่อ, ศาลากลาง, โทรศัพท์, ติดต่อจังหวัด, ศูนย์ดำรงธรรม, สายด่วน, ที่อยู่', '', 'citizen/complaints', '2026-08-26 06:29:22', '2026-08-26 06:29:22'),
('4', 'ต้องการชำระหรือยื่นแบบภาษีท้องถิ่นและภาษีป้าย ทำอย่างไร?', 'ภาษี, บำรุงท้องที่, ภาษีโรงเรือน, ภาษีป้าย, จ่ายภาษี, ค่าธรรมเนียม, ท้องถิ่น', '', '#services', '2026-08-26 06:29:22', '2026-08-26 06:29:22'),
('5', 'ขั้นตอนการยื่นขอกำหนดเลขที่บ้านและอนุญาตก่อสร้าง (e-Permission)', 'ก่อสร้าง, ถมดิน, เลขที่บ้าน, e-permission, โครงสร้าง, ขออนุญาต', '', '#services', '2026-08-26 06:29:22', '2026-08-26 06:29:22'),
('6', 'แนะนำสถานที่ท่องเที่ยวสุดฮิตในจังหวัดพัทลุงให้หน่อย', 'ท่องเที่ยว, ที่พัก, โรงแรม, คาเฟ่, ร้านอาหาร, งานประเพณี, เที่ยว, ทะเลน้อย, ล่องแก่ง, เขาอกทะลุ', '', 'http://www.ma-muanglung.com', '2026-08-26 06:29:22', '2026-08-26 06:29:22'),
('7', 'ติดต่อศาลากลางจังหวัดพัทลุงและหน่วยงานราชการได้อย่างไร?', 'เบอร์โทร, เบอร์ติดต่อ, ศาลากลาง, โทรศัพท์, ติดต่อจังหวัด, ศูนย์ดำรงธรรม, สายด่วน, ที่อยู่', '', 'citizen/complaints', '2026-08-26 06:29:22', '2026-08-26 06:29:22'),
('8', 'แนะนำสถานที่ท่องเที่ยวให้หน่อย', 'แหล่งท่องเที่ยว,สถานที่ท่องเที่ยว,แนะนำแหล่งท่องเที่ยว,มาเมืองลุง,ข้อมูลด้านการท่องเที่ยว', 'ถ้าเกี่ยวกับการท่องเที่ยว น้องแนะนำให้ไปที่เว็บไซต์  \"มาเมืองลุง\" นะคะ', 'http://www.ma-muanglung.com', '2026-08-26 10:02:45', '2026-08-26 10:02:45'),
('9', 'คำขวัญประจำจังหวัดพัทลุงและมรดกทางวัฒนธรรมคืออะไร?', 'คำขวัญ, คำขวัญจังหวัด, พัทลุงคืออะไร, สวนขวัญเมือง, มรดก, โนรา, มโนราห์', '✨ **คำขวัญจังหวัดพัทลุง**: \"เมืองหนังโนรา อู่นาข้าว พราวน้ำตก แหล่งนกน้ำ ถ้ำเย็นตา ภูเขาอกทะลุ น้ำพุร้อน\"\n\nศิลปะการแสดง **\"โนรา\" (Nora)** ได้รับการขึ้นทะเบียนจาก UNESCO ให้เป็นมรดกทางวัฒนธรรมที่จับต้องไม่ได้ของมนุษยชาติ ซึ่งพัทลุงเป็นแผ่นดินต้นกำเนิดแห่งมนต์ขลังนี้ค่ะ ', 'http://www.ma-muanglung.go.th', '2026-08-26 10:02:45', '2026-08-26 10:02:45'),
('10', 'ติดต่อศาลากลางและหน่วยงานภายในจังหวัดได้อย่างไร?', 'เบอร์โทร, เบอร์ติดต่อ, ศาลากลาง, โทรศัพท์, ติดต่อจังหวัด, ศูนย์ดำรงธรรม, สายด่วน, ที่อยู่', '', 'citizen/complaints', '2026-08-26 10:02:45', '2026-08-26 10:02:45'),
