 McLaren Racing</title> \r\n<style type=\"text/css\">\r\n  @font-face {\r\n    font-family: \'Google Sans\';\r\n    font-style: normal;\r\n    font-weight: 400;\r\n    mso-font-alt: Arial;\r\n    src: local(\'Google Sans Regular\'), local(\'GoogleSans-Regular\'), url(\'https://fonts.gstatic.com/s/googlesans/v6/4UaGrENHsxJlGDuGo1OIlL3Owps.ttf\') format(\'truetype\');\r\n  }\r\n  @font-face {\r\n    font-family: \'Google Sans\';\r\n    font-style: normal;\r\n    font-weight: 500;\r\n    mso-font-alt: Arial;\r\n    src: local(\'Google Sans Medium\'), local(\'GoogleSans-Medium\'), url(\'https://fonts.gstatic.com/s/googlesans/v6/4UabrENHsxJlGDuGo1OIlLU94YtzCwM.ttf\') format(\'truetype\');\r\n  }\r\n  @font-face {\r\n    font-family: \'Google Sans\';\r\n    font-style: normal;\r\n    font-weight: 700;\r\n    mso-font-alt: Arial;\r\n    src: local(\'Google Sans Bold\'), local(\'GoogleSans-Bold\'), url(\'https://fonts.gstatic.com/s/googlesans/v6/4UabrENHsxJlGDuGo1OIlLV154tzCwM.ttf\') format(\'truetype\');\r\n  }\r\n  @font-face {\r\n    font-family: \'Google Sans Text\';\r\n    font-weight: 700;\r\n    mso-font-alt: Arial;\r\n    font-style: normal;\r\n    src: url(\'https://lp.cloudplatformonline.com/rs/808-GJW-314/images/googlesanstext-bold-webfont.woff2\') format(\'woff2\'),\r\n        url(\'https://lp.cloudplatformonline.com/rs/808-GJW-314/images/googlesanstext-bold-webfont.woff\') format(\'woff\'),\r\n        url(\'https://lp.cloudplatformonline.com/rs/808-GJW-314/images/GoogleSansText-Bold.ttf\') format(\'truetype\');\r\n  }\r\n  @font-face {\r\n    font-family: \'Google Sans Text\';\r\n    font-style: normal;\r\n    font-weight: 500;\r\n    mso-font-alt: Arial;\r\n    src: url(\'https://lp.cloudplatformonline.com/rs/808-GJW-314/images/googlesanstext-medium-webfont.woff2\') format(\'woff2\'),\r\n        url(\'https://lp.cloudplatformonline.com/rs/808-GJW-314/images/googlesanstext-medium-webfont.woff\') format(\'woff\'),\r\n        url(\'https://lp.cloudplatformonline.