_rps\"><th class=\"column_width col-rps \" style=\"width:100%;\" width=\"100%\" valign=\"top\" align=\"center\" id=\"ctb_2_0\"><div class=\"\"><div class=\"\"><div class=\"\"><table class=\"tm_table\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr><td id=\"elb_41\" width=\"100%\" valign=\"top\" align=\"center\" style=\"padding:0px 0px 0px 0px ;\"><table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#72cc45;\" class=\"type_25\"><tbody><tr><td><table class=\"tm_table tm_headline\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"border-spacing: 0;\"><tbody><tr><td ref=\"Headline\" class=\"element_object tm_custom\" align=\"left\" style=\" padding:10px 20px 10px 20px ;\"><table class=\"wrap_headline\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"font-family: Arial, sans-serif; color: rgb(0, 0, 0);\"><tbody><tr><td><div class=\"fr-view\" style=\"display: block;\"><div style=\"text-align: center;\"><span style=\"font-family: Tahoma; color: rgb(255, 255, 255); font-size: 24px;\">พบกับโอกาสในการสร้างการรับรู้ของแบรนด์</span></div><div style=\"text-align: center;\"><span style=\"font-family: Tahoma; color: rgb(255, 255, 255); font-size: 24px;\">เข้าถึงกลุ่มเป้าหมาย และเชื่อมต่อกับ</span></div><div style=\"text-align: center;\"><span style=\"font-family: Tahoma; color: rgb(255, 255, 255); font-size: 24px;\">ผู้มีอำนาจตัดสินใจใ</span><span style=\"background-color: initial; font-family: Tahoma; color: rgb(255, 255, 255); font-size: 24px;\">นอุตสาหกรรม<br>การจัดงานสินค้า&nbsp;</span><span style=\"background-color: initial; color: rgb(255, 255, 255); font-family: Tahoma; font-size: 24px;\">การประชุม และอีเวนต์</span></div></div></td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></div></div></div></th></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></div></td></tr><tr><td class=\"obj_contain_row footer\" valign=\"top\" align=\"center\"><table class=\"tm_table\" id=\"tm_footer\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr><td valign=\"top\" align=\"center\" id=\"tm_footer_row\"><div class=\"tm_row\" style=\"position:relative;\"><table align=\"center\" width=\"100%\" style=\"width:100%;\" class=\"\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr><td align=\"center\"><table align=\"center\" width=\"100%\" style=\"max-width:600px;\" class=\"tm_table tm_rs tm_footer\" ref=\"BODY\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr><td align=\"center\"><table class=\"tm_table tm_rs\" style=\"position:relative;border-spacing: 0 !important;border-collapse: collapse !important;margin: 0 auto !important;\" align=\"center\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr class=\"wrap_col_rps\"><th class=\"column_width col-rps tm-col-rps\" style=\"width:100%;\" width=\"100%\" valign=\"top\" align=\"center\" id=\"ctb_3_0\"><div class=\"\"><div class=\"\"><div class=\"\"><table class=\"tm_table\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr><td id=\"elb_42\" width=\"100%\" valign=\"top\" align=\"center\" style=\"padding:0px 0px 0px 0px ;\"><table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" class=\"type_1\"><tbody><tr><td><table class=\"tm_table tm_text\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"border-spacing: 0;\"><tbody><tr><td ref=\"Text\" class=\"element_object tm_custom\" align=\"left\" style=\" padding:10px 20px 10px 20px ;\"><table class=\"wrap_txt\" style=\"font-weight: normal; font-family: Arial, sans-serif; font-size: 15px; color: rgb(77, 77, 77); line-height: 1.4;\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr><td><div class=\"fr-view\" style=\"display: block;\"><div><br></div><div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">ท่านกำลังมองหาช่องทางเพิ่มการมองเห็นให้แบรนด์ และเข้าถึงลูกค้าใหม่อยู่หรือไม่?</span></span></div><div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\"><br></span></span></div><div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">TMX 2027 เปิดโอกาสให้แบรนด์ของท่านได้พบกับผู้ประกอบการ ผู้ออกงานแสดงสินค้าเป็นประจำ ผู้จัดงาน ผู้ซื้อ และผู้มีอำนาจตัดสินใจจากธุรกิจที่เกี่ยวข้องกับงานแสดงสินค้า งานประชุม และงานอีเวนต์</span></span></div><div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\"><br></span></span></div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\"><strong>แบรนด์ของคุณจะเข้าถึงใครบ้าง?</strong></span></span><ul data-spread=\"false\"><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">บริษัทและเจ้าของแบรนด์ ผู้ที่ออกงานแสดงสินค้าต่างๆเป็นประจำ</span></span></li><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">ผู้จัดงานแสดงสินค้าและงานประชุม</span></span></li><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">ผู้จัดงานอีเวนต์และเทศกาล</span></span></li><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">ฝ่ายการตลาดและฝ่ายจัดซื้อ</span></span></li><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">บริษัทอีเวนต์และเอเจนซี</span></span></li><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">หน่วยงานภาครัฐ สมาคม และสถาบันการศึกษา</span></span></li></ul><div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">นี่คือโอกาสในการพบคู่ค้าและลูกค้าใหม่ สร้างพันธมิตรทางธุรกิจ และนำเสนอสินค้าและบริการของคุณให้ตรงกับกลุ่มเป้าหมาย <br><br></span></span></div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\"><strong>การเป็นผู้สนับสนุน TMX 2027 ช่วยให้แบรนด์ของคุณ</strong></span></span><ul data-spread=\"false\"><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">เป็นที่รู้จักมากขึ้น</span></span></li><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">เข้าถึงกลุ่มลูกค้าที่ตรงเป้าหมาย</span></span></li><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">สร้างการจดจำในกลุ่มผู้มีอำนาจตัดสินใจ</span></span></li><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">เพิ่มโอกาสในการสร้างลูกค้าและพันธมิตรใหม่</span></span></li><li><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">โปรโมตแบรนด์ทั้งภายในงานและผ่านช่องทางออนไลน์</span></span></li><li><span style=\"font-family: Tahoma; color: rgb(0, 0, 0);\">นำเสนอสินค้า บริการ หรือโซลูชันของคุณได้อย่างโดดเด่น</span></li></ul><div><div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\"><strong>เลือกรูปแบบที่เหมาะกับแบรนด์ของคุณTMX 2027&nbsp;</strong></span></span></div><div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\"><br></span></span></div><div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\">มีรูปแบบการสนับสนุนให้เลือกหลายแบบ ตั้งแต่การแสดงโลโก้ในพื้นที่สำคัญ การสนับสนุนเวทีและกิจกรรม ไปจนถึงการโปรโมตผ่านสื่อออนไลน์ของงานไม่ว่าคุณต้องการสร้างการรับรู้ เปิดตัวสินค้า หรือเข้าถึงลูกค้าใหม่ &nbsp;</span></span><span style=\"background-color: initial; color: rgb(0, 0, 0); font-family: Tahoma; text-align: center;\">ทีมงาน TMX พร้อมช่วยแนะนำรูปแบบที่เหมาะกับ</span></div><div><span style=\"background-color: initial; color: rgb(0, 0, 0); font-family: Tahoma; text-align: center;\">เป้าหมายของคุณสร้างการมองเห็นให้แบรนด์ และเริ่มต้นโอกาสทางธุรกิจใหม่ในงาน&nbsp;</span></div><div><span style=\"background-color: initial; color: rgb(0, 0, 0); font-family: Tahoma; text-align: center;\">TMX 2027</span></div><div><span style=\"color: rgb(0, 0, 0);\"><span style=\"font-family: Tahoma;\"><br></span></span></div><div><span style=\"color: rgb(0, 0, 0); font-family: Tahoma;\"><strong>TMX 2027</strong><br>29–30 เมษายน 2570</span></div><div><span style=\"color: rgb(0, 0, 0); font-family: Tahoma;\">ฮอลล์ 6 อิมแพ็ค เมืองทองธานี</span><br><br></div></div></div></td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></div></div></div></th></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table></div><div class=\"tm_row\" style=\"position:relative;\"><table align=\"center\" width=\"100%\" style=\"width:100%;\" class=\"\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr><td align=\"center\"><table align=\"center\" width=\"100%\" style=\"max-width:600px;\" class=\"tm_table tm_rs tm_footer\" ref=\"BODY\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr><td align=\"center\"><table class=\"tm_table tm_rs\" style=\"position:relative;border-spacing: 0 !important;border-collapse: collapse !important;margin: 0 auto !important;\" align=\"center\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr class=\"wrap_col_rps\"><th class=\"column_width col-rps\" style=\"width:100%;\" width=\"100%\" valign=\"top\" align=\"center\" id=\"ctb_4_0\"><div class=\"\"><div class=\"\"><div class=\"\"><table class=\"tm_table\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr><td id=\"elb_43\" width=\"100%\" valign=\"top\" align=\"center\" style=\"padding:0px 0px 0px 0px ;\"><table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" class=\"type_10\"><tbody><tr><td><table class=\"tm_table tm_button\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"border-spacing: 0;\"><tbody><tr><td ref=\"Button\" class=\"element_object tm_custom\" align=\"left\" style=\" padding:10px 20px 10px 20px ;\"><table class=\"wrap_btn\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"><tbody><tr><td align=\"center\"><table class=\"link_btn\" style=\"border: 1px solid #ffffff;border-radius:30px;background-color:#19177a;color:#ffffff;font-size:f_20px;font-weight:bo