('27', '16965', '', '@', 'phatthalung@moi.go.th', 'ข้อมูลการติดต่อ phatthalung.go.th', 'Untitled Document\r\n			\r\n			\r\n			\r\n			\r\n			body,td,th {\r\n			font-size: 12px;\r\n			font-family: Arial, Helvetica, sans-serif;\r\n			}\r\n			fieldset{\r\n			width:350px;\r\n			padding:5px;\r\n			}\r\n			\r\n			มีการติดต่อจากระบบติดต่อเราของเว็บไซต์  phatthalung.go.th \r\n			คุณ  ต้องการติดต่อเรื่อง  โดยมีรายละเอียดดังนี้\r\n			\r\n			หากคุณต้องการติดต่อกลับ คุณ  กรุณาส่งจดหมายกลับไปยัง', '\r\n			<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n			<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n			<head>\r\n			<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n			<title>Untitled Document</title>\r\n			</head>\r\n			\r\n			<body>\r\n			<style type=\"text/css\">\r\n			body,td,th {\r\n			font-size: 12px;\r\n			font-family: Arial, Helvetica, sans-serif;\r\n			}\r\n			fieldset{\r\n			width:350px;\r\n			padding:5px;\r\n			}\r\n			</style>\r\n			<h3>มีการติดต่อจากระบบติดต่อเราของเว็บไซต์  phatthalung.go.th</h3> <br />\r\n			<p>คุณ  ต้องการติดต่อเรื่อง  โดยมีรายละเอียดดังนี้</p><br />\r\n			<p></p><br />\r\n			<p><strong>หากคุณต้องการติดต่อกลับ คุณ  กรุณาส่งจดหมายกลับไปยัง </strong></p>\r\n			\r\n			</body>\r\n			</html>\r\n			\r\n			\r\n\r\n', '2026-08-09 01:59:15', '0', NULL, '0', '0', 'inbox', '2026-08-31 09:06:46', '2026-08-31 09:06:46'),
