-- --------------------------------------------------------
-- Table structure for `services`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `services`;
CREATE TABLE `services` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `service_name` varchar(200) NOT NULL,
  `description` varchar(300) DEFAULT NULL,
  `icon_class` varchar(100) NOT NULL DEFAULT 'fa-solid fa-laptop-file',
  `external_url` varchar(255) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `settings`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `setting_key` varchar(100) NOT NULL,
  `setting_value` text,
  `setting_group` varchar(50) NOT NULL DEFAULT 'general',
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`setting_key`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `site_banners`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `site_banners`;
CREATE TABLE `site_banners` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL,
  `subtitle` varchar(255) DEFAULT NULL,
  `badge_title` varchar(100) DEFAULT NULL,
  `badge_icon` varchar(100) DEFAULT NULL,
  `bg_type` varchar(50) NOT NULL DEFAULT 'image',
  `image_path` varchar(255) DEFAULT NULL,
  `floating_img_path` varchar(255) DEFAULT NULL,
  `floating_pos` varchar(50) DEFAULT NULL,
  `floating_anim` varchar(50) DEFAULT NULL,
  `card_placement` varchar(50) DEFAULT NULL,
  `desc` text,
